const DISPLAY = { y: -11, w: 50.2, h: 19.0, winW: 50.8, winH: 19.6 };
const VISOR = { w: 62, ep: 1.8, top: 15.4, bottom: 11.5 }; // par rapport au centre de l'afficheur
const PLATE = { w: 40, h: 10, r: 1.5, screw: 16, gaugeDy: 30.5, displayDy: 17 };
const VALUE = { gap: 2.5, scale: 1.2 }; // valeur en % sous la plaquette (carte seulement, pas sur l'objet)
