const LAMP = {
  y: GAUGE.y + PLATE.gaugeDy, w: 40, h: 18, r: 0.6, winW: 27, winH: 10.5, maskW: 26.6, maskH: 10.1,
  rivet: 17.4, rivetR: 1.0,
  hood: { w: 31, ep: 1.3, top: 6.85, bottom: 0.5, cheek: 1.3 }, // visière : toit et joues, par rapport au centre
};
const FHC_R = 3.0; // tête fraisée M3 (fraisure Ø 6,4)
const CHC_R = 2.75; // tête cylindrique M3 (Ø 5,5)

const SEGMENTS = {
  0: "abcdef", 1: "bc", 2: "abged", 3: "abgcd", 4: "fgbc", 5: "afgcd",
  6: "afgedc", 7: "abc", 8: "abcdefg", 9: "abcdfg", "-": "g", " ": "",
};

const STYLE = `
  :host {
    display: block;
    --cm-kaki: #5c623c;
    --cm-kaki-light: #80865a;
    --cm-kaki-dark: #3a3e25;
    --cm-panel: #353330;
    --cm-black: #1c1b19;
    --cm-plate: #262523;
    --cm-ink: #eceae2;
    --cm-needle: #e8251a;
    --cm-value: #dedbd2;
    --cm-face: #0f0e0d;
    --cm-seg-off: #2a2620;
    --cm-seg-on: #ffb31a;
    --cm-lamp-off: #a29e94;
    --cm-lamp-amber: #ff8f1f;
    --cm-lamp-red: #ff2a14;
  }
  ha-card { display: block; padding: 12px; overflow: hidden; }
  svg { display: block; width: 100%; height: auto; }
  .kaki { fill: var(--cm-kaki); }
  .panel { fill: var(--cm-panel); }
  .black { fill: var(--cm-black); }
  .plate { fill: var(--cm-plate); }
  .ink { fill: var(--cm-ink); }
  .needle-ink { fill: var(--cm-needle); }
  .val { fill: var(--cm-value); transition: opacity 0.6s; }
  .stale .val { opacity: 0.4; }
  .face { fill: var(--cm-face); }
  .hit { cursor: pointer; outline: none; }
  .ring { fill: none; stroke: var(--primary-color, #03a9f4); stroke-width: 0.8; opacity: 0; }
  .hit:focus-visible .ring { opacity: 1; }
  .needle { transition: transform 3s cubic-bezier(0.4, 0.1, 0.3, 1); }
  .seg { fill: var(--cm-seg-off); transition: fill 0.2s, opacity 0.6s; }
  .seg.on { fill: var(--cm-seg-on); }
  .seg.on.blink { animation: blink 1s step-end infinite; }
  @keyframes blink { 50% { fill: var(--cm-seg-off); } }
  .stale .seg.on { opacity: 0.35; }
  .stale .lit { filter: none; }
  .lamp-ink { fill: var(--cm-lamp-off); }
  .lamp[data-state="amber"] { --cm-lamp: var(--cm-lamp-amber); }
  .lamp[data-state="red"] { --cm-lamp: var(--cm-lamp-red); }
  .lamp-light { opacity: 0; fill: var(--cm-lamp, transparent); transition: opacity 0.3s; }
  .lamp[data-state="amber"] .lamp-light { opacity: 1; animation: lamp-breathe 1.6s ease-in-out infinite alternate; }
  .lamp[data-state="red"] .lamp-light { opacity: 1; animation: lamp-blink 1s step-end infinite; }
  @keyframes lamp-breathe { to { opacity: 0.35; } }
  @keyframes lamp-blink { 50% { opacity: 0; } }
  @media (prefers-reduced-motion: reduce) {
    .needle { transition-duration: 0.01s; }
    .seg.on.blink { animation: none; }
    .lamp[data-state] .lamp-light { animation: none; }
  }
`;

// ---------------------------------------------------------------- dessin

const n = (v) => +v.toFixed(3);

function hex(r, deg) {
  const pts = [];
  for (let k = 0; k < 6; k++) {
    const a = ((deg + 60 * k) * Math.PI) / 180;
    pts.push(`${n(r * Math.cos(a))} ${n(r * Math.sin(a))}`);
  }
  return `M${pts.join("L")}Z`;
}

function screw(x, y, r, socket, deg) {
  return `<g transform="translate(${x} ${y})">
    <circle r="${r}" fill="url(#g-screw)"/>
    <circle r="${r}" fill="none" stroke="#000" stroke-opacity=".5" stroke-width=".2"/>
    <path d="${hex(socket, deg)}" fill="#050505"/>
  </g>`;
}

// Texte composé glyphe par glyphe (Barlow Condensed SemiBold, comme les
// plaquettes), centré sur x = 0, ligne de base en y = 0.
function glyphText(str) {
  const G = ASSETS.glyphs;
  let x = 0;
  const parts = [];
  for (const ch of str) {
    const g = G.chars[ch];
    if (g) parts.push(`<path transform="translate(${n(x)} 0)" d="${g.d}" fill-rule="evenodd"/>`);
    x += (g ? g.w : G.space) + G.track;
  }
  return `<g transform="translate(${n(-(x - G.track) / 2)} 0)">${parts.join("")}</g>`;
}

function roundRect(w, h, r) {
  const x = w / 2 - r;
  const y = h / 2 - r;
  return `M${-x} ${-h / 2}H${x}A${r} ${r} 0 0 1 ${w / 2} ${-y}V${y}A${r} ${r} 0 0 1 ${x} ${h / 2}`
    + `H${-x}A${r} ${r} 0 0 1 ${-w / 2} ${y}V${-y}A${r} ${r} 0 0 1 ${-x} ${-h / 2}Z`;
}

function plate(key, y) {
  const { w, h, r, screw: sx } = PLATE;
  return `<g transform="translate(0 ${y})">
    <rect class="plate" x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" rx="${r}" filter="url(#sh-sm)"/>
    <path d="M${-w / 2 + r} ${-h / 2 + 0.2}H${w / 2 - r}" stroke="#fff" stroke-opacity=".12" stroke-width=".3"/>
    <path class="ink" d="${ASSETS.plate[key]}" fill-rule="evenodd"/>
    ${screw(-sx, 0, FHC_R, 1.155, 17)}${screw(sx, 0, FHC_R, 1.155, 41)}
  </g>`;
}

function gauge(key, dialKey, x) {
  const D = ASSETS.dial;
  const S = D.spec;
  const R = S.window_r;
  const chord = -S.chord_z;
  const pivot = -S.pivot_z;
  const cx = n(Math.sqrt(R * R - chord * chord));
  const L = S.needle_len;
  const needle = `M-.45 2.5L.45 2.5L.3 0L.07 ${-L}L-.07 ${-L}L-.3 0Z`;
  const rest = `style="transform: rotate(${-S.sweep_deg / 2}deg)"`; // aiguille au repos, sur 0
  const c = GAUGE.collar / 2;
  const s = GAUGE.screw;
  return `<g class="hit" data-key="${key}" tabindex="0" role="button" transform="translate(${x} ${GAUGE.y})">
    <title></title>
    <rect class="ring" x="${-c - 1}" y="${-c - 1}" width="${2 * c + 2}" height="${2 * c + 2}" rx="2"/>
    <rect class="black" x="${-c}" y="${-c}" width="${2 * c}" height="${2 * c}" rx=".8" filter="url(#sh)"/>
    <path d="M${-c + 0.8} ${-c + 0.2}H${c - 0.8}" stroke="#fff" stroke-opacity=".1" stroke-width=".3"/>
    ${screw(-s, -s, CHC_R, 1.443, 8)}${screw(s, -s, CHC_R, 1.443, 35)}
    ${screw(-s, s, CHC_R, 1.443, 52)}${screw(s, s, CHC_R, 1.443, 23)}
    <circle r="${GAUGE.bezel}" fill="url(#g-bezel)" filter="url(#sh-sm)"/>
    <circle r="${R + 0.35}" fill="url(#g-bezel-in)"/>
    <g clip-path="url(#win)">
      <circle r="${R}" fill="${D.rgb.fond}"/>
      <path d="${D.scale}" fill="${D.rgb.echelle}" fill-rule="evenodd"/>
      <path d="${D.zone}" fill="${D.rgb.zone}" fill-rule="evenodd"/>
      <path d="${D.text[dialKey]}" fill="${D.rgb.texte}" fill-rule="evenodd"/>
      <circle r="${R}" fill="url(#g-recess)"/>
      <g transform="translate(.35 ${pivot + 0.6})" opacity=".55" filter="url(#blur)">
        <g class="needle" ${rest}><path d="${needle}"/></g>
      </g>
      <g transform="translate(0 ${pivot})"><g class="needle" ${rest}><path class="needle-ink" d="${needle}"/></g></g>
      <path d="M${-cx} ${chord}A${R} ${R} 0 0 0 ${cx} ${chord}Z" fill="url(#g-mask)"/>
      <circle r="${R}" fill="url(#g-glass)"/>
      <path d="M-16.8 -8A18.6 18.6 0 0 1 -8 -16.8" fill="none" stroke="#fff" stroke-opacity=".16" stroke-width=".5" stroke-linecap="round"/>
    </g>
    ${plate(dialKey, PLATE.gaugeDy)}
    <g class="val" transform="translate(0 ${n(PLATE.gaugeDy + PLATE.h / 2 + VALUE.gap + ASSETS.glyphs.cap * VALUE.scale)}) scale(${VALUE.scale})"></g>
  </g>`;
}

function display() {
  const { w, h, winW, winH } = DISPLAY;
  const V = VISOR;
  const xo = V.w / 2;
  const xi = xo - V.ep;
  const roof = -V.top + V.ep;
  const digits = ASSETS.seg.digits
    .map((d, i) => Object.entries(d).map(([s, p]) => `<path class="seg" data-digit="${i}" data-seg="${s}" d="${p}"/>`).join(""))
    .join("");
  return `<g class="hit" data-key="display" tabindex="0" role="button" transform="translate(0 ${DISPLAY.y})">
    <title></title>
    <rect class="ring" x="${-xo - 1}" y="${-V.top - 1}" width="${2 * xo + 2}" height="${V.top + PLATE.displayDy + PLATE.h / 2 + 2}" rx="2"/>
    <rect x="${-xi}" y="${roof}" width="${2 * xi}" height="${V.bottom - roof}" fill="#000" fill-opacity=".14"/>
    <rect x="${-winW / 2}" y="${-winH / 2}" width="${winW}" height="${winH}" fill="#050505"/>
    <rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" class="face"/>
    <rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" fill="url(#g-face)"/>
    <rect x="${-xi}" y="${roof}" width="${2 * xi}" height="10" fill="url(#g-roof)"/>
    <g class="lit" filter="url(#glow)">
      ${digits}
      <path class="seg" data-colon="1" d="${ASSETS.seg.colon}"/>
      <path class="seg" d="${ASSETS.seg.dp}"/>
    </g>
    <path class="kaki" d="M${-xo} ${-V.top}H${xo}V${V.bottom}H${xi}V${roof}H${-xi}V${V.bottom}H${-xo}Z" filter="url(#sh-visor)"/>
    <path d="M${-xo + 0.3} ${-V.top + 0.25}H${xo - 0.3}" stroke="#fff" stroke-opacity=".22" stroke-width=".4"/>
    ${plate("reinit", PLATE.displayDy)}
  </g>`;
}

// Voyant : cadre kaki riveté, légende CLAUDE dans un masque noir, petite
// visière. La légende éteinte reste visible ; la couche allumée (lueur et
// lettres) prend la couleur de l'état : ambre qui respire, rouge qui clignote.
function lamp() {
  const L = LAMP;
  const V = L.hood;
  const xo = V.w / 2;
  const xi = xo - V.cheek;
  const roof = -V.top + V.ep;
  const rivet = (x) => `<g transform="translate(${x} 0)">
    <circle r="${L.rivetR}" fill="url(#g-rivet)"/>
    <circle r="${L.rivetR}" fill="none" stroke="#000" stroke-opacity=".45" stroke-width=".15"/>
  </g>`;
  return `<g class="hit lamp" data-key="lamp" data-state="off" tabindex="0" role="button" transform="translate(0 ${L.y})">
    <title></title>
    <rect class="ring" x="${-L.w / 2 - 1}" y="${-L.h / 2 - 1}" width="${L.w + 2}" height="${L.h + 2}" rx="2"/>
    <path class="kaki" d="${roundRect(L.w, L.h, L.r)}M${-L.winW / 2} ${-L.winH / 2}V${L.winH / 2}H${L.winW / 2}V${-L.winH / 2}Z" fill-rule="evenodd" filter="url(#sh-sm)"/>
    <path d="M${-L.w / 2 + L.r} ${-L.h / 2 + 0.2}H${L.w / 2 - L.r}" stroke="#fff" stroke-opacity=".2" stroke-width=".3"/>
    <rect x="${-L.winW / 2}" y="${-L.winH / 2}" width="${L.winW}" height="${L.winH}" fill="#050505"/>
    <rect x="${-L.maskW / 2}" y="${-L.maskH / 2}" width="${L.maskW}" height="${L.maskH}" class="face"/>
    <g clip-path="url(#lamp-win)" opacity=".35"><ellipse class="lamp-light" rx="${n(ASSETS.lamp.width / 2 + 2)}" ry="${n(ASSETS.lamp.cap)}" filter="url(#haze)"/></g>
    <path class="lamp-ink" d="${ASSETS.lamp.d}" fill-rule="evenodd"/>
    <g filter="url(#glow)"><path class="lamp-light" d="${ASSETS.lamp.d}" fill-rule="evenodd"/></g>
    <rect x="${-xi}" y="${roof}" width="${2 * xi}" height="4" fill="url(#g-roof)"/>
    ${rivet(-L.rivet)}${rivet(L.rivet)}
    <path class="kaki" d="M${-xo} ${-V.top}H${xo}V${-V.bottom}H${xi}V${roof}H${-xi}V${-V.bottom}H${-xo}Z" filter="url(#sh-hood)"/>
    <path d="M${-xo + 0.3} ${-V.top + 0.2}H${xo - 0.3}" stroke="#fff" stroke-opacity=".22" stroke-width=".3"/>
  </g>`;
}

function face() {
  const C = COQUE;
  const P = PLATINE;
  const { x: sx, y: sy } = PLATINE_SCREWS;
  const H = C.h / 2;
  const W = C.w / 2;
  const e = 2.5 / C.h; // arrondi de la façade (coque_Rf), en fraction de la hauteur
  return `<svg viewBox="-104 -52 208 106" role="img" aria-label="Claudemètre">
  <defs>
    <filter id="sh-lg" x="-5%" y="-8%" width="112%" height="125%">
      <feDropShadow dx=".6" dy="1.6" stdDeviation="1.6" flood-opacity=".45"/>
    </filter>
    <filter id="sh" x="-10%" y="-10%" width="125%" height="130%">
      <feDropShadow dx=".4" dy=".9" stdDeviation=".6" flood-opacity=".6"/>
    </filter>
    <filter id="sh-sm" x="-10%" y="-20%" width="125%" height="150%">
      <feDropShadow dx=".25" dy=".5" stdDeviation=".35" flood-opacity=".6"/>
    </filter>
    <filter id="sh-visor" x="-10%" y="-10%" width="125%" height="140%">
      <feDropShadow dx=".6" dy="1.8" stdDeviation="1.1" flood-opacity=".6"/>
    </filter>
    <filter id="sh-hood" x="-10%" y="-20%" width="125%" height="170%">
      <feDropShadow dx=".35" dy="1" stdDeviation=".6" flood-opacity=".6"/>
    </filter>
    <filter id="blur"><feGaussianBlur stdDeviation=".3"/></filter>
    <filter id="haze" x="-30%" y="-80%" width="160%" height="260%"><feGaussianBlur stdDeviation="1.6"/></filter>
    <filter id="glow" x="-5%" y="-15%" width="110%" height="130%">
      <feGaussianBlur in="SourceGraphic" stdDeviation=".55" result="b"/>
      <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
    </filter>
    <clipPath id="win"><circle r="${ASSETS.dial.spec.window_r}"/></clipPath>
    <clipPath id="lamp-win"><rect x="${-LAMP.maskW / 2}" y="${-LAMP.maskH / 2}" width="${LAMP.maskW}" height="${LAMP.maskH}"/></clipPath>
    <linearGradient id="g-coque" gradientUnits="userSpaceOnUse" x1="0" y1="${-H}" x2="0" y2="${H}">
      <stop offset="0" style="stop-color: var(--cm-kaki-light)"/>
      <stop offset="${n(e)}" style="stop-color: var(--cm-kaki)"/>
      <stop offset="${n(1 - e)}" style="stop-color: var(--cm-kaki)"/>
      <stop offset="1" style="stop-color: var(--cm-kaki-dark)"/>
    </linearGradient>
    <linearGradient id="g-coque-side" gradientUnits="userSpaceOnUse" x1="${-W}" y1="0" x2="${W}" y2="0">
      <stop offset="0" stop-color="#fff" stop-opacity=".12"/>
      <stop offset="${n(2.5 / C.w)}" stop-color="#fff" stop-opacity="0"/>
      <stop offset="${n(1 - 2.5 / C.w)}" stop-color="#000" stop-opacity="0"/>
      <stop offset="1" stop-color="#000" stop-opacity=".3"/>
    </linearGradient>
    <linearGradient id="g-panel" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#fff" stop-opacity=".05"/>
      <stop offset="1" stop-color="#000" stop-opacity=".12"/>
    </linearGradient>
    <radialGradient id="g-screw" cx=".38" cy=".32" r=".75">
      <stop offset="0" stop-color="#5a5855"/>
      <stop offset=".55" stop-color="#1f1e1c"/>
      <stop offset="1" stop-color="#0a0a09"/>
    </radialGradient>
    <radialGradient id="g-rivet" cx=".38" cy=".32" r=".75">
      <stop offset="0" stop-color="#e6e6e8"/>
      <stop offset=".5" stop-color="#8d8d90"/>
      <stop offset="1" stop-color="#3a3a3c"/>
    </radialGradient>
    <linearGradient id="g-bezel" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#5b5853"/>
      <stop offset=".45" stop-color="#2b2927"/>
      <stop offset="1" stop-color="#0d0c0b"/>
    </linearGradient>
    <linearGradient id="g-bezel-in" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#0b0a0a"/>
      <stop offset="1" stop-color="#47433f"/>
    </linearGradient>
    <radialGradient id="g-recess" cx=".5" cy=".45" r=".52">
      <stop offset=".8" stop-color="#000" stop-opacity="0"/>
      <stop offset="1" stop-color="#000" stop-opacity=".6"/>
    </radialGradient>
    <linearGradient id="g-mask" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#2a2826"/>
      <stop offset="1" stop-color="#171615"/>
    </linearGradient>
    <linearGradient id="g-glass" x1="0" y1="0" x2=".8" y2="1">
      <stop offset="0" stop-color="#fff" stop-opacity=".14"/>
      <stop offset=".42" stop-color="#fff" stop-opacity=".04"/>
      <stop offset=".5" stop-color="#fff" stop-opacity="0"/>
    </linearGradient>
    <linearGradient id="g-face" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#fff" stop-opacity=".07"/>
      <stop offset=".5" stop-color="#fff" stop-opacity="0"/>
    </linearGradient>
    <linearGradient id="g-roof" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#000" stop-opacity=".6"/>
      <stop offset="1" stop-color="#000" stop-opacity="0"/>
    </linearGradient>
  </defs>
  <rect x="${-W}" y="${-H}" width="${C.w}" height="${C.h}" rx="${C.r}" fill="url(#g-coque)" filter="url(#sh-lg)"/>
  <rect x="${-W}" y="${-H}" width="${C.w}" height="${C.h}" rx="${C.r}" fill="url(#g-coque-side)"/>
  <rect class="panel" x="${-P.w / 2}" y="${-P.h / 2}" width="${P.w}" height="${P.h}" rx="${P.r}" filter="url(#sh)"/>
  <rect x="${-P.w / 2}" y="${-P.h / 2}" width="${P.w}" height="${P.h}" rx="${P.r}" fill="url(#g-panel)"/>
  <path d="M${-P.w / 2 + P.r} ${-P.h / 2 + 0.2}H${P.w / 2 - P.r}" stroke="#fff" stroke-opacity=".14" stroke-width=".35"/>
  ${screw(-sx, -sy, FHC_R, 1.155, 12)}${screw(sx, -sy, FHC_R, 1.155, 47)}
  ${screw(-sx, sy, FHC_R, 1.155, 29)}${screw(sx, sy, FHC_R, 1.155, 5)}
  ${gauge("session", "session", -GAUGE.x)}
  ${gauge("week", "semaine", GAUGE.x)}
  ${display()}
  ${lamp()}
</svg>`;
}

// ---------------------------------------------------------------- données

function percent(st) {
  const v = Number.parseFloat(st?.state);
  return Number.isFinite(v) ? v : null;
}

function instant(st) {
  const t = Date.parse(st?.state ?? "");
  return Number.isFinite(t) ? t : null;
}

const clocks = new Map();

// HH:MM dans le fuseau de Home Assistant.
function clock(ms, timeZone) {
  const key = timeZone || "";
  let f = clocks.get(key);
  if (!f) {
    const opts = { hour: "2-digit", minute: "2-digit", hourCycle: "h23" };
    try {
      f = new Intl.DateTimeFormat("fr-FR", { ...opts, timeZone: timeZone || undefined });
    } catch {
      f = new Intl.DateTimeFormat("fr-FR", opts); // fuseau inconnu du navigateur
    }
    clocks.set(key, f);
  }
  const parts = f.formatToParts(ms);
  const part = (type) => parts.find((p) => p.type === type)?.value ?? "--";
  return `${part("hour").padStart(2, "0")}:${part("minute").padStart(2, "0")}`;
}

// Mêmes règles que l'appareil (cahier des charges § 3) : reset dépassé → 0 %
// et --:--, sans attendre HA ; capteur inconnu → aiguille au repos et --:--.
function readings(hass, config, now) {
  const e = config.entities;
  const st = (id) => (id ? hass.states[id] : undefined);
  const sessionReset = instant(st(e.session_reset));
  const weekReset = instant(st(e.week_reset));
  const sessionOver = sessionReset !== null && sessionReset <= now;
  const weekOver = weekReset !== null && weekReset <= now;
  let stale = false;
  if (e.last_measure) {
    const last = instant(st(e.last_measure));
    stale = last === null || now - last > config.stale_after * 60000;
  }
  return {
    session: sessionOver ? 0 : percent(st(e.session)),
    week: weekOver ? 0 : percent(st(e.week)),
    clock: sessionReset === null || sessionOver ? "--:--" : clock(sessionReset, hass.config?.time_zone),
    stale,
    ...activity(st(e.active), st(e.attention)),
  };
}

// Voyant : rouge si un agent attend une réponse (prioritaire), ambre si un
// agent travaille, éteint sinon (capteurs inconnus ou absents compris).
function activity(active, attention) {
  const count = (st, attr) => {
    const v = Number.parseInt(st?.attributes?.[attr], 10);
    return Number.isFinite(v) && v > 1 ? ` (${v} ${attr})` : "";
  };
  if (attention?.state === "on") return { lamp: "red", lampLabel: `Claude attend une réponse${count(attention, "demandes")}` };
  if (active?.state === "on") return { lamp: "amber", lampLabel: `Claude au travail${count(active, "agents")}` };
  const known = [active, attention].some((st) => st?.state === "off");
  return { lamp: "off", lampLabel: known ? "Claude au repos" : "Activité de Claude inconnue" };
}

// ---------------------------------------------------------------- carte

class ClaudemetreCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._timer = null;
    this._key = null;
    this._ready = false;
    this._shown = {};
  }

  setConfig(config) {
    if (!config || typeof config !== "object") throw new Error("Configuration invalide");
    const ent = config.entities;
    if (ent !== undefined && (ent === null || typeof ent !== "object" || Array.isArray(ent))) {
      throw new Error("« entities » : session, week, session_reset, week_reset, last_measure, active, attention");
    }
    const stale = Number(config.stale_after ?? DEFAULTS.stale_after);
    if (!(stale > 0)) throw new Error("« stale_after » : un nombre de minutes > 0");
    this._config = { ...DEFAULTS, ...config, entities: { ...DEFAULTS.entities, ...ent }, stale_after: stale };
    this._key = null;
    this._build();
    if (this._hass) this.hass = this._hass;
  }

  set hass(hass) {
    this._hass = hass;
    if (!this._config) return;
    const e = this._config.entities;
    const st = (id) => (id ? hass.states[id] : undefined);
    const key = [
      ...[e.session, e.week, e.session_reset, e.week_reset, e.last_measure].map((id) => st(id)?.state),
      st(e.active)?.state, st(e.active)?.attributes?.agents,
      st(e.attention)?.state, st(e.attention)?.attributes?.demandes,
      hass.config?.time_zone,
    ].join("|");
    if (key === this._key) return;
    this._key = key;
    this._update();
  }

  get hass() {
    return this._hass;
  }

  connectedCallback() {
    this._timer = setInterval(() => this._update(), TICK_MS);
    // Deux images avant de poser les aiguilles : la transition part du repos.
    requestAnimationFrame(() => requestAnimationFrame(() => {
      this._ready = true;
      this._update();
    }));
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    this._timer = null;
    this._ready = false;
  }

  getCardSize() {
    return 4;
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6 };
  }

  static getStubConfig() {
    return {};
  }

  _build() {
    if (this._els) return;
    this.shadowRoot.innerHTML = `<style>${STYLE}</style><ha-card>${face()}</ha-card>`;
    const root = this.shadowRoot;
    const hit = (key) => root.querySelector(`.hit[data-key="${key}"]`);
    this._els = {
      svg: root.querySelector("svg"),
      session: { hit: hit("session"), needles: hit("session").querySelectorAll(".needle"), value: hit("session").querySelector(".val") },
      week: { hit: hit("week"), needles: hit("week").querySelectorAll(".needle"), value: hit("week").querySelector(".val") },
      display: { hit: hit("display") },
      lamp: { hit: hit("lamp") },
      digits: [0, 1, 2, 3].map((i) => {
        const segs = {};
        root.querySelectorAll(`.seg[data-digit="${i}"]`).forEach((p) => (segs[p.dataset.seg] = p));
        return segs;
      }),
      colon: root.querySelector(".seg[data-colon]"),
    };
    const e = () => this._config.entities;
    const entity = {
      session: () => e().session,
      week: () => e().week,
      display: () => e().session_reset,
      // Voyant : l'attente quand il est rouge, l'activité sinon.
      lamp: () => (this._shown.lamp === "red" ? e().attention : e().active || e().attention),
    };
    for (const [key, target] of Object.entries(entity)) {
      const el = this._els[key].hit;
      const open = () => this._moreInfo(target());
      el.addEventListener("click", open);
      el.addEventListener("keydown", (ev) => {
        if (ev.key === "Enter" || ev.key === " ") {
          ev.preventDefault();
          open();
        }
      });
    }
    this._showClock("--:--");
  }

  _update() {
    if (!this._hass || !this._els) return;
    const r = readings(this._hass, this._config, Date.now());
    if (this._ready) {
      this._needle("session", r.session, "Session (5 h)");
      this._needle("week", r.week, "Semaine (7 j)");
    }
    this._showClock(r.clock);
    this._els.svg.classList.toggle("stale", r.stale);
    const label = `Réinitialisation de la session : ${r.clock}${r.stale ? " (données anciennes)" : ""}`;
    this._els.display.hit.querySelector("title").textContent = label;
    this._els.display.hit.setAttribute("aria-label", label);
    this._showLamp(r.lamp, r.lampLabel);
  }

  _showLamp(state, label) {
    const el = this._els.lamp.hit;
    if (this._shown.lamp !== state) {
      this._shown.lamp = state;
      el.dataset.state = state;
    }
    el.querySelector("title").textContent = label;
    el.setAttribute("aria-label", label);
  }

  _needle(key, pct, name) {
    const v = pct === null ? 0 : Math.min(100, Math.max(0, pct));
    const sweep = ASSETS.dial.spec.sweep_deg;
    const deg = n(-sweep / 2 + (sweep * v) / 100);
    const el = this._els[key];
    if (this._shown[key] !== deg) {
      this._shown[key] = deg;
      el.needles.forEach((g) => (g.style.transform = `rotate(${deg}deg)`));
    }
    const text = pct === null ? "-- %" : `${Math.round(v)} %`;
    if (el.value.dataset.text !== text) {
      el.value.dataset.text = text;
      el.value.innerHTML = glyphText(text);
    }
    const label = `${name} : ${pct === null ? "inconnu" : text}`;
    el.hit.querySelector("title").textContent = label;
    el.hit.setAttribute("aria-label", label);
  }

  _showClock(text) {
    if (this._shown.clock === text) return;
    this._shown.clock = text;
    const chars = text.replace(":", "").split("");
    this._els.digits.forEach((segs, i) => {
      const lit = SEGMENTS[chars[i]] ?? "";
      for (const [s, p] of Object.entries(segs)) p.classList.toggle("on", lit.includes(s));
    });
    this._els.colon.classList.toggle("on", text.includes(":"));
    // Deux-points qui clignote (allumé 0,5 s par seconde) quand une heure est affichée ; fixe sur --:--.
    this._els.colon.classList.toggle("blink", text !== "--:--");
  }

  _moreInfo(entityId) {
    if (!entityId) return;
    this.dispatchEvent(new CustomEvent("hass-more-info", { detail: { entityId }, bubbles: true, composed: true }));
  }
}

if (!customElements.get("claudemetre-card")) {
  customElements.define("claudemetre-card", ClaudemetreCard);
  window.customCards = window.customCards || [];
  window.customCards.push({
    type: "claudemetre-card",
    name: "Claudemètre",
    description: "Usage du forfait Claude : jauges session et semaine, heure de réinitialisation, voyant d'activité.",
    preview: true,
  });
  console.info(`%c CLAUDEMETRE-CARD %c ${VERSION} `, "color:#1c1b19;background:#ffb31a;font-weight:700", "color:#ffb31a;background:#1c1b19");
}
